#include <stdio.h>
#include <stdlib.h>

static int check(long long D, int n, const long long *u, const long long *v, 
                 long long u_min, long long u_max, long long v_min, long long v_max) {
    long long diff_u = u_max - u_min;
    long long diff_v = v_max - v_min;

    if (diff_u <= D && diff_v <= D) {
        return 1;
    }

    if (diff_u > D && diff_v <= D) {
        long long limit1 = u_min + D;
        long long limit2 = u_max - D;
        for (int i = 0; i < n; i++) {
            if (u[i] > limit1 && u[i] < limit2) {
                return 0;
            }
        }
        return 1;
    }

    if (diff_u <= D && diff_v > D) {
        long long limit1 = v_min + D;
        long long limit2 = v_max - D;
        for (int i = 0; i < n; i++) {
            if (v[i] > limit1 && v[i] < limit2) {
                return 0;
            }
        }
        return 1;
    }

    // Both diff_u > D and diff_v > D
    // Config 1:
    // Box A: u <= u_min + D && v <= v_min + D
    // Box B: u >= u_max - D && v >= v_max - D
    long long u_lim1 = u_min + D, v_lim1 = v_min + D;
    long long u_lim2 = u_max - D, v_lim2 = v_max - D;
    int ok1 = 1;
    for (int i = 0; i < n; i++) {
        int in_A = (u[i] <= u_lim1 && v[i] <= v_lim1);
        int in_B = (u[i] >= u_lim2 && v[i] >= v_lim2);
        if (!in_A && !in_B) {
            ok1 = 0;
            break;
        }
    }
    if (ok1) return 1;

    // Config 2:
    // Box A: u <= u_min + D && v >= v_max - D
    // Box B: u >= u_max - D && v <= v_min + D
    int ok2 = 1;
    for (int i = 0; i < n; i++) {
        int in_A = (u[i] <= u_lim1 && v[i] >= v_lim2);
        int in_B = (u[i] >= u_lim2 && v[i] <= v_lim1);
        if (!in_A && !in_B) {
            ok2 = 0;
            break;
        }
    }
    return ok2;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long *x = (long long *)malloc(n * sizeof(long long));
    long long *y = (long long *)malloc(n * sizeof(long long));
    long long *u = (long long *)malloc(n * sizeof(long long));
    long long *v = (long long *)malloc(n * sizeof(long long));

    for (int i = 0; i < n; i++) {
        scanf("%lld", &x[i]);
    }
    for (int i = 0; i < n; i++) {
        scanf("%lld", &y[i]);
    }

    if (n <= 2) {
        printf("0\n");
        free(x); free(y); free(u); free(v);
        return 0;
    }

    long long u_min = 4e18, u_max = -4e18;
    long long v_min = 4e18, v_max = -4e18;

    for (int i = 0; i < n; i++) {
        u[i] = x[i] + y[i];
        v[i] = x[i] - y[i];
        if (u[i] < u_min) u_min = u[i];
        if (u[i] > u_max) u_max = u[i];
        if (v[i] < v_min) v_min = v[i];
        if (v[i] > v_max) v_max = v[i];
    }

    long long low = 0, high = 2000000000LL;
    long long ans = high;

    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (check(mid, n, u, v, u_min, u_max, v_min, v_max)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    printf("%lld\n", ans);

    free(x);
    free(y);
    free(u);
    free(v);

    return 0;
}
